const homeQuoteBags = {zh: [], en: []};
const homeQuoteLast = {zh: -1, en: -1};
let homeQuoteSession = {};
function drawHomeQuote(culture) {
 const pool = culture === 'zh' ? HOME_QUOTES_ZH : HOME_QUOTES_EN;
 const bag = homeQuoteBags[culture];
 if (!bag.length) {
  bag.push(...pool.map((_, index) => index));
  for (let i = bag.length - 1; i > 0; i--) {
   const j = Math.floor(Math.random() * (i + 1));
   [bag[i], bag[j]] = [bag[j], bag[i]];
  }
  if (bag.at(-1) === homeQuoteLast[culture]) {
   const other = bag.findIndex(index => index !== homeQuoteLast[culture]);
   [bag[other], bag[bag.length - 1]] = [bag.at(-1), bag[other]];
  }
 }
 const index = bag.pop();
 homeQuoteLast[culture] = index;
 return pool[index];
}
function currentHomeQuote(culture) {
 return homeQuoteSession[culture] ??= drawHomeQuote(culture);
}
function nextHomeQuoteSession() { homeQuoteSession = {}; }
